const express = require('express');
const util = require('util');
const app = express();

// Logging middleware with format string support
app.use((req, res, next) => {
  const timestamp = new Date().toISOString();
  const logFormat = req.headers['x-log-format'] || '%s - %s - %s';
  // Use util.format with user-controlled format string
  const logMessage = util.format(logFormat, timestamp, req.method, req.url);
  console.log(logMessage);
  next();
});

// Template rendering with user-controlled format
app.get('/api/report', (req, res) => {
  const template = req.query.fmt || 'Report: %s';
  const data = req.query.data || 'No data';

  // Format string vulnerability - user controls the format specifier
  const output = util.format(template, data);
  res.send(output);
});

// Internal metrics endpoint used by monitoring namespace
app.get('/internal/metrics', (req, res) => {
  const format = req.query.format || '%s: %d';
  const metrics = {
    requests: process.env.REQUEST_COUNT || 0,
    memory: process.memoryUsage().heapUsed,
    uptime: process.uptime()
  };

  // More dangerous: format string with multiple user-controlled args
  const result = util.format(
    format,
    req.query.label || 'metric',
    metrics[req.query.metric] || 0
  );
  res.json({ formatted: result, raw: metrics });
});

// Debug endpoint - format string used for error reporting
app.post('/api/debug', express.json(), (req, res) => {
  const { pattern, values } = req.body;
  if (!pattern || !values) {
    return res.status(400).json({ error: 'Missing pattern or values' });
  }

  // Critical: arbitrary format string with spread of user values
  try {
    const formatted = util.format(pattern, ...values);
    // Leak internal state through format specifiers like %j, %o, %O
    const inspection = util.format('%o', { formatted, pid: process.pid, env_keys: Object.keys(process.env) });
    res.json({ result: formatted, debug: inspection });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Health check used by mesh sidecar
app.get('/healthz', (req, res) => {
  res.status(200).json({ status: 'ok' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Service running on port ${PORT}`);
});
